<?php $product = $product ?? []; $vendorMode = $vendorMode ?? false; $featureText = $product ? implode("\n", array_column(product_features((int)$product['id']), 'feature')) : ''; $faqText = $product ? implode("\n", array_map(fn($f)=>$f['question'].'|'.$f['answer'], product_faqs((int)$product['id']))) : ''; $changeText = $product ? implode("\n", array_map(fn($c)=>$c['version'].'|'.$c['notes'], product_changelog((int)$product['id']))) : ''; ?>
<form method="post" class="grid gap-6 xl:grid-cols-[1fr_380px]"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><section class="grid gap-5 rounded-3xl border border-white/10 bg-white/5 p-6"><h2 class="text-2xl font-black">Basic Fields</h2><div class="grid gap-4 md:grid-cols-2"><label class="field">Product Name<input name="name" value="<?= e($product['name'] ?? '') ?>" required></label><label class="field">Slug<input name="slug" value="<?= e($product['slug'] ?? '') ?>"></label></div><div class="grid gap-4 md:grid-cols-3"><label class="field">Product Type<select name="product_type"><?php foreach (['Theme','Script','Plugin','Template','App','Service','UI Kit','Course'] as $type): ?><option <?= ($product['product_type'] ?? '')===$type?'selected':'' ?>><?= e($type) ?></option><?php endforeach; ?></select></label><label class="field">Category<select name="category_id"><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (int)($product['category_id'] ?? 0)===(int)$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><?php if (!$vendorMode): ?><label class="field">Vendor<select name="vendor_id"><option value="">Marketplace</option><?php foreach ($vendors as $vendor): ?><option value="<?= (int)$vendor['id'] ?>" <?= (int)($product['vendor_id'] ?? 0)===(int)$vendor['id']?'selected':'' ?>><?= e($vendor['store_name']) ?></option><?php endforeach; ?></select></label><?php else: ?><input type="hidden" name="vendor_id" value="<?= (int)($vendors[0]['id'] ?? 0) ?>"><?php endif; ?></div><label class="field">Short Description<textarea name="short_description" rows="3" required><?= e($product['short_description'] ?? '') ?></textarea></label><label class="field">Full Description / Rich Editor<textarea name="full_description" rows="7"><?= e($product['full_description'] ?? '') ?></textarea></label><div class="grid gap-4 md:grid-cols-4"><label class="field">Tags<input name="tags" value="<?= e($product['tags'] ?? '') ?>"></label><label class="field">Version<input name="version" value="<?= e($product['version'] ?? '1.0.0') ?>"></label><label class="field">Release Date<input type="date" name="release_date" value="<?= e($product['release_date'] ?? date('Y-m-d')) ?>"></label><label class="field">Last Updated<input type="date" name="last_updated" value="<?= e($product['last_updated'] ?? date('Y-m-d')) ?>"></label></div><h2 class="text-2xl font-black">Pricing Fields</h2><div class="grid gap-4 md:grid-cols-3"><label class="field">Regular Price<input type="number" step="0.01" name="regular_price" value="<?= e($product['regular_price'] ?? 0) ?>"></label><label class="field">Sale Price<input type="number" step="0.01" name="sale_price" value="<?= e($product['sale_price'] ?? '') ?>"></label><label class="field">Extended License Price<input type="number" step="0.01" name="extended_license_price" value="<?= e($product['extended_license_price'] ?? '') ?>"></label><label class="field">Subscription Price<input type="number" step="0.01" name="subscription_price" value="<?= e($product['subscription_price'] ?? '') ?>"></label><label class="field">Offer Expiry<input type="date" name="offer_expiry" value="<?= e($product['offer_expiry'] ?? '') ?>"></label><label class="flex items-center gap-2 font-bold"><input type="checkbox" name="is_free" <?= !empty($product['is_free'])?'checked':'' ?>> Free Download</label></div><h2 class="text-2xl font-black">Demo & Media Fields</h2><div class="grid gap-4 md:grid-cols-2"><?php foreach (['live_preview_url'=>'Live Preview URL','admin_demo_url'=>'Admin Demo URL','documentation_url'=>'Documentation URL','video_preview_url'=>'Video Preview URL','download_preview_url'=>'Download Preview ZIP','thumbnail'=>'Thumbnail','featured_banner'=>'Featured Banner','product_logo'=>'Product Logo','screenshot_gallery'=>'Screenshot Gallery','mobile_screenshots'=>'Mobile Screenshots','gif_preview'=>'GIF Preview','video_showcase'=>'Video Showcase'] as $name=>$label): ?><label class="field"><?= e($label) ?><input name="<?= e($name) ?>" value="<?= e($product[$name] ?? '') ?>" <?= $name==='thumbnail'?'required':'' ?>></label><?php endforeach; ?></div><h2 class="text-2xl font-black">Compatibility, SEO & Download System</h2><div class="grid gap-4 md:grid-cols-3"><?php foreach (['compatible_browsers'=>'Compatible Browsers','compatible_cms'=>'Compatible CMS','php_version'=>'PHP Version','framework'=>'Framework','meta_title'=>'Meta Title','meta_description'=>'Meta Description','focus_keywords'=>'Focus Keywords','og_image'=>'OpenGraph Image','structured_data'=>'Structured Data JSON','canonical_url'=>'Canonical URL','robots_control'=>'Robots Control','main_download_file'=>'Main Download File','additional_files'=>'Additional Files','file_size'=>'File Size','download_limit'=>'Download Limit','license_type'=>'License Type','support_expiry'=>'Support Expiry','auto_update_token'=>'Auto Update Token'] as $name=>$label): ?><label class="field"><?= e($label) ?><input name="<?= e($name) ?>" value="<?= e($product[$name] ?? ($name==='robots_control'?'index,follow':'')) ?>"></label><?php endforeach; ?></div><div class="grid gap-3 md:grid-cols-5"><?php foreach (['responsive'=>'Responsive','retina_ready'=>'Retina Ready','dark_mode'=>'Dark Mode','rtl_support'=>'RTL Support','multi_language'=>'Multi Language'] as $name=>$label): ?><label class="flex items-center gap-2 font-bold"><input type="checkbox" name="<?= e($name) ?>" <?= (int)($product[$name] ?? ($name==='rtl_support'?0:1))===1?'checked':'' ?>> <?= e($label) ?></label><?php endforeach; ?></div><div class="grid gap-4 md:grid-cols-3"><label class="field">Features<textarea name="features" rows="6"><?= e($featureText) ?></textarea></label><label class="field">FAQs (Q|A)<textarea name="faqs" rows="6"><?= e($faqText) ?></textarea></label><label class="field">Changelog (Version|Notes)<textarea name="changelog" rows="6"><?= e($changeText) ?></textarea></label></div></section><aside class="grid content-start gap-4 rounded-3xl border border-white/10 bg-white/5 p-6"><label class="field">Status<select name="status"><option value="draft" <?= ($product['status'] ?? '')==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= ($product['status'] ?? '')==='published'?'selected':'' ?>>Published</option></select></label><label class="field">Approval<select name="approval_status"><option value="pending" <?= ($product['approval_status'] ?? '')==='pending'?'selected':'' ?>>Pending</option><option value="approved" <?= ($product['approval_status'] ?? 'approved')==='approved'?'selected':'' ?>>Approved</option><option value="rejected" <?= ($product['approval_status'] ?? '')==='rejected'?'selected':'' ?>>Rejected</option></select></label><button class="rounded-2xl bg-cyan-300 p-4 font-black text-slate-950">Save Product</button><p class="text-sm text-slate-400">This form covers the complete PSP Marketplace product meta blueprint.</p></aside></form>
